<script setup lang="ts">import {onMounted,watch,ref,computed} from 'vue';import {useStudies} from '../stores/studies';import {useMeasurements} from '../stores/measurements';import {useAuth} from '../stores/auth';import {useTask} from '../hooks/useTask';import {grades} from '../constants/enums';import type {Treatment,Reading} from '../types/domain';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StudySelect from '../components/StudySelect.vue';const study=useStudies(),data=useMeasurements(),auth=useAuth(),{error,busy,perform}=useTask(),editT=ref<Treatment|null>(null),editR=ref<Reading|null>(null),filter=ref(0),message=ref('');const visible=computed(()=>data.readings.filter(r=>!filter.value||r.treatment_id===filter.value));onMounted(()=>perform(async()=>{await study.load();await data.load(study.selected)}));watch(()=>study.selected,id=>{editT.value=null;editR.value=null;filter.value=0;message.value='';perform(()=>data.load(id))});async function saveT(e:Event){const f=new FormData(e.target as HTMLFormElement);await data.saveTreatment({...Object.fromEntries(f),study_id:study.selected},study.selected,editT.value?.id);editT.value=null;message.value='工艺口径已保存。'}async function saveR(e:Event){const f=new FormData(e.target as HTMLFormElement);await data.saveReading({...Object.fromEntries(f),study_id:study.selected,treatment_id:Number(f.get('treatment_id')),grade:Number(f.get('grade'))},study.selected,editR.value?.id);editR.value=null;message.value='独立试样等级已保存；历史快照保持原样。'}const name=(id:number)=>data.treatments.find(t=>t.id===id)?.name;</script><template><PageHeading no="02" title="来源与口径" sub="独立试样逐份核对；形成等级只能为1–9整数，重复编号不会被当成新证据。"/><StudySelect/><ErrorNotice :error="error"/><p v-if="message" class="success" role="status">{{message}}</p><div class="data-spread"><section><h2 class="ruled-title">预定义工艺 <small>{{data.treatments.length}}组 / 全部进入检验</small></h2><article class="treatment-entry" v-for="t in data.treatments" :key="t.id"><div><small>{{t.code}}</small><h3>{{t.name}}</h3><p>{{t.process_note}}</p><b>{{data.readings.filter(r=>r.treatment_id===t.id).length}}份独立试样</b></div><button v-if="auth.canEdit" class="small-button" @click="editT=t">编辑</button></article><details v-if="auth.canEdit" class="edit-fold" :open="!!editT"><summary>{{editT?'编辑工艺口径':'＋ 登记工艺'}}</summary><form :key="editT?.id||'new'" @submit.prevent="e=>perform(()=>saveT(e))"><label>工艺编号<input name="code" :value="editT?.code" minLength="2" required/></label><label>工艺名称<input name="name" :value="editT?.name" minLength="2" required/></label><label>工艺与独立单位说明<textarea name="process_note" :value="editT?.process_note"/></label><button :disabled="busy">保存工艺</button><button v-if="editT" type="button" @click="editT=null">取消</button></form></details><aside class="margin-note">每组至少5份，2–5组。试样ID唯一只能防止显式重复，不能证明不存在批次相关；独立性需由制备和抽样设计保障。</aside></section><section><div class="section-line"><h2>等级来源台账</h2><label class="inline-select">工艺<select aria-label="筛选工艺" v-model.number="filter"><option :value="0">全部预定义工艺</option><option v-for="t in data.treatments" :value="t.id" :key="t.id">{{t.code}} {{t.name}}</option></select></label></div><details v-if="auth.canEdit" class="edit-fold" :open="!!editR"><summary>{{editR?'编辑 '+editR.specimen_code:'＋ 录入一份独立试样'}}</summary><form class="form-grid" :key="editR?.id||'new'" @submit.prevent="e=>perform(()=>saveR(e))"><label>独立试样编号<input name="specimen_code" :value="editR?.specimen_code" required minLength="2"/></label><label>所属工艺<select name="treatment_id" :value="editR?.treatment_id||data.treatments[0]?.id"><option v-for="t in data.treatments" :value="t.id" :key="t.id">{{t.code}} {{t.name}}</option></select></label><label>形成等级<select name="grade" :value="editR?.grade||1"><option v-for="g in grades" :key="g" :value="g">等级 {{g}}</option></select></label><label>来源说明<input name="source_note" :value="editR?.source_note"/></label><div class="button-row"><button class="primary" :disabled="busy||!data.treatments.length">保存等级</button><button v-if="editR" type="button" @click="editR=null">取消编辑</button></div></form></details><div class="table-scroll"><table><thead><tr><th>独立试样</th><th>工艺</th><th>形成等级</th><th v-if="auth.canEdit"/></tr></thead><tbody><tr v-for="r in visible" :key="r.id"><td>{{r.specimen_code}}<small>{{r.source_note}}</small></td><td>{{name(r.treatment_id)}}</td><td class="grade-value">{{r.grade}}</td><td v-if="auth.canEdit"><button class="small-button" @click="editR=r">编辑</button></td></tr></tbody></table></div><p v-if="!visible.length" class="empty">先登记工艺，再为每组录入至少5份独立试样。空组会保留并导致检验失败。</p></section></div></template>